import json
import re
from typing import Dict, List, Tuple

SECTION_RE = re.compile(r"^\s*\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.+?)\s*->\s*(\S+)\s*$")
LINE_RE = re.compile(r"^\s*([^:]+?):\s*(.+?)\s*->\s*(\S+)\s*$")
BARE_RE = re.compile(r"^\s*(.+?)\s*->\s*(\S+)\s*$")


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_index: Dict[str, Dict[str, str]] = {}

    current_id: str | None = None
    current_lines: List[str] = []

    def add_node(node_id: str, text_value: str, speaker: str, node_type: str) -> None:
        if node_id in node_index:
            return
        node = {"id": node_id, "text": text_value, "speaker": speaker, "type": node_type}
        node_index[node_id] = node
        nodes.append(node)

    def flush_section() -> None:
        nonlocal current_id, current_lines
        if current_id is None:
            return
        lines = [line.strip() for line in current_lines if line.strip()]
        if not lines:
            add_node(current_id, "", "", "line")
            current_id = None
            current_lines = []
            return

        if all(CHOICE_RE.match(line) for line in lines):
            add_node(current_id, "", "", "choice")
            for line in lines:
                match = CHOICE_RE.match(line)
                if not match:
                    continue
                choice_text = match.group(1).strip()
                target = match.group(2).strip()
                edges.append({"from": current_id, "to": target, "text": choice_text})
            current_id = None
            current_lines = []
            return

        line = lines[0]
        match = LINE_RE.match(line)
        if match:
            speaker = match.group(1).strip()
            text_value = match.group(2).strip()
            target = match.group(3).strip()
            add_node(current_id, text_value, speaker, "line")
            edges.append({"from": current_id, "to": target, "text": ""})
        else:
            match = BARE_RE.match(line)
            if match:
                text_value = match.group(1).strip()
                target = match.group(2).strip()
                add_node(current_id, text_value, "", "line")
                edges.append({"from": current_id, "to": target, "text": ""})
            else:
                add_node(current_id, line, "", "line")
        current_id = None
        current_lines = []

    for raw_line in text.splitlines():
        header = SECTION_RE.match(raw_line)
        if header:
            flush_section()
            current_id = header.group(1).strip()
            current_lines = []
            continue
        if current_id is not None:
            current_lines.append(raw_line)

    flush_section()

    existing_ids = {node["id"] for node in nodes}
    for edge in edges:
        target = edge["to"]
        if target not in existing_ids:
            add_node(target, "", "", "line")
            existing_ids.add(target)

    return {"nodes": nodes, "edges": edges}


def _escape_dot(text: str) -> str:
    return text.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")


def _to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines: List[str] = ["digraph Dialogue {", "  rankdir=LR;"]
    for node in graph["nodes"]:
        node_id = _escape_dot(node["id"])
        label = node["id"]
        if node["type"] == "line":
            if node["speaker"] or node["text"]:
                label = f"{node['id']}\\n{node['speaker']}: {node['text']}".strip()
        label = _escape_dot(label)
        shape = "box" if node["type"] == "line" else "diamond"
        lines.append(f"  \"{node_id}\" [label=\"{label}\", shape={shape}];")
    for edge in graph["edges"]:
        src = _escape_dot(edge["from"])
        dst = _escape_dot(edge["to"])
        label = _escape_dot(edge["text"]) if edge["text"] else ""
        if label:
            lines.append(f"  \"{src}\" -> \"{dst}\" [label=\"{label}\"];\n")
        else:
            lines.append(f"  \"{src}\" -> \"{dst}\";")
    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as handle:
        text = handle.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as handle:
        json.dump(graph, handle, indent=2, ensure_ascii=True)

    dot_text = _to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as handle:
        handle.write(dot_text)


if __name__ == "__main__":
    main()
